CREATE OR REPLACE FUNCTION public.admin_user_directory_page(_search text DEFAULT '',_role text DEFAULT '',_sort text DEFAULT 'created_at',_ascending boolean DEFAULT false,_limit integer DEFAULT 25,_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE source jsonb; result jsonb; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'عرض المستخدمين للأدمن فقط'; END IF; source:=public.admin_user_directory(); WITH filtered AS (SELECT value FROM jsonb_array_elements(source) WHERE (_role='' OR value->>'role'=_role) AND (_search='' OR lower(value::text) LIKE '%'||lower(_search)||'%')), ordered AS (SELECT value FROM filtered ORDER BY CASE WHEN _ascending THEN value->>CASE WHEN _sort IN ('created_at','display_name','full_name','email','role') THEN _sort ELSE 'created_at' END END ASC NULLS LAST,CASE WHEN NOT _ascending THEN value->>CASE WHEN _sort IN ('created_at','display_name','full_name','email','role') THEN _sort ELSE 'created_at' END END DESC NULLS LAST,value->>'user_id' LIMIT least(greatest(_limit,1),500) OFFSET greatest(_offset,0)) SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(value) FROM ordered),'[]'::jsonb),'count',(SELECT count(*) FROM filtered)) INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.admin_user_directory_page(text,text,text,boolean,integer,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_user_directory_page(text,text,text,boolean,integer,integer) TO authenticated;
SELECT to_regprocedure('public.admin_user_directory_page(text,text,text,boolean,integer,integer)') IS NOT NULL AS paged_directory_ready;